{* Code generated by packages/kit-compose/src/build.ts from src/map.ts + variants/. DO NOT EDIT. *}
{* Breadcrumb: Box nav > ol > li, Link or Text span. Includes inherit variables: shadowed params are passed explicitly. *}
{parameters
  array $items = [],
  string $ariaLabel = '',
  string $class = '',
  array $attrs = [],
}
{capture $lis}{foreach $items as $it}{var $c = 'text-sm ' . (($it['current'] ?? false) ? 'font-medium' : (($it['disabled'] ?? false) ? 'text-muted-foreground' : 'text-primary underline-offset-4 hover:underline'))}{var $a = ($it['current'] ?? false) ? ['aria-current' => 'page'] : []}{capture $inner}{if ($it['href'] ?? '') !== '' && !($it['disabled'] ?? false)}{include '../ui/link/Link.latte', href: $it['href'], class: $c, ariaLabel: null, attrs: $a, children: htmlspecialchars((string) ($it['label'] ?? ''), \ENT_QUOTES)}{else}{include '../ui/text/Text.latte', tag: 'span', class: $c, attrs: $a, children: htmlspecialchars((string) ($it['label'] ?? ''), \ENT_QUOTES)}{/if}{/capture}{include '../ui/box/Box.latte', tag: 'li', class: 'inline-flex items-center', attrs: [], children: (string) $inner}{/foreach}{/capture}
{capture $ol}{include '../ui/box/Box.latte', tag: 'ol', class: 'flex flex-wrap items-center gap-2', attrs: [], children: (string) $lis}{/capture}
{include '../ui/box/Box.latte', tag: 'nav', class: \CodegenX\Compose\Latte\Compose::join(['text-sm', $class]), attrs: ['aria-label' => $ariaLabel !== '' ? $ariaLabel : 'Breadcrumb', ...$attrs], children: (string) $ol}
